VM=$(az vm list -g resume-builder --query "[0].name" -o tsv) && IP=${VM}PublicIP && { [ -n "$(az network public-ip show -g resume-builder -n $IP --query dnsSettings.fqdn -o tsv)" ] || az network public-ip update -g resume-builder -n $IP --dns-name freeatsresume-$RANDOM -o none --only-show-errors; } && rm -f ~/.ssh/rb_deploy ~/.ssh/rb_deploy.pub && ssh-keygen -t ed25519 -f ~/.ssh/rb_deploy -N "" -q -C github-deploy && az vm run-command invoke -g resume-builder -n $VM --command-id RunShellScript --scripts "echo '$(cat ~/.ssh/rb_deploy.pub)' > /home/azureuser/.ssh/authorized_keys" -o none && echo "===== SERVER_IP =====" && az network public-ip show -g resume-builder -n $IP --query ipAddress -o tsv && echo "===== DOMAIN =====" && az network public-ip show -g resume-builder -n $IP --query dnsSettings.fqdn -o tsv && echo "===== SSH_PRIVATE_KEY =====" && cat ~/.ssh/rb_deploy
